static long ka_ioctl(struct file *file, unsigned int cmd, unsigned long arg)
{
    struct ka_request req;
    int ret;

    switch (cmd) {
    case KA_IOCTL_WRITE:
    case KA_IOCTL_READ:
    case KA_IOCTL_DEBUG:
        // Copy the request structure from user space
        if (copy_from_user(&req, (void __user *)arg, sizeof(struct ka_request))) {
            return -EFAULT;
        }

        // Validate the length before proceeding
        if (req.len > KA_BUF_SIZE) {
            return -EINVAL; // Length exceeds the buffer capacity
        }

        // Now pass the validated request to the handlers
        if (cmd == KA_IOCTL_WRITE) {
            ret = ka_handle_write(file, &req);
        } else if (cmd == KA_IOCTL_READ) {
            ret = ka_handle_read(file, &req);
        } else { // KA_IOCTL_DEBUG
            ret = ka_handle_debug(file, &req);
        }
        return ret;

    default:
        return -ENOTTY;
    }
}
